// Prop functions
const makeAura = (color, size = 1, sizemult = 4) => {
    return {
        POSITION: [sizemult * size, 0, 0, 0, -2],
        SHAPE: 0,
        COLOR: color,
        IS_AURA: true
    };
};
const makeShell = (options = {}) => {
    options.size = options.size == null ? 1 : options.size;
    options.shape = options.shape == null ? 6 : options.shape;
    options.color = options.color == null ? 9 : options.color;
    options.rpm = options.rpm == null ? 4 : options.rpm == 0 ? undefined : options.rpm;
    options.angle = options.angle == null ? 0 : options.angle;
    options.dip = options.dip == null ? 1 : options.dip;
    return {
        POSITION: [1.17 * options.size, 0, 0, options.angle, -1],
        SHAPE: options.shape,
        COLOR: options.color,
        RPM: options.rpm,
        DIP: options.dip,
    }
};
const fixPoint = (x, y, n) => {
    return [
        x * Math.cos(n) - y * Math.sin(n),
        x * Math.sin(n) + y * Math.cos(n),
    ];
}

// Tools for abilities
const timer = (execute, duration) => {
    let timer = setInterval(() => execute(), 31.25);
    setTimeout(() => {
        clearInterval(timer);
    }, duration * 1000);
};

// Abilities
const crit = (me, them, multiplier, chance) => {
    if (!them) return
    if (Math.floor(Math.random() * 101) + 1 < chance && (them.type == 'tank' || them.type == 'miniboss')) {
        me.damage *= multiplier * 2;
        me.source.sendMessage('Crit landed!');
        them.sendMessage(me.source.name + ' landed a critical hit on you!');
    }
};

const ice = (them, multiplier, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode) timer(() => {
        them.velocity.x /= 1.05 * multiplier;
        them.velocity.y /= 1.05 * multiplier;
    }, 1.5 * duration);
};
const poison = (me, them, multiplier, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.poisoned) {
        them.variables.poisoned = true;
        setTimeout(() => {
            them.variables.poisoned = false;
        }, 2 * duration * 1000);
        timer(() => {
            if (them.variables.poisoned && them.health.amount > 10) {
                them.health.amount -= multiplier * 0.5;
                if (them.onDamaged) them.onDamaged(them, me, multiplier * 0.5)
                if (me.onDealtDamage) me.onDealtDamage(me, them.multiplier * 0.5)
                if (me.onDealtDamageUniv) me.onDealtDamageUniv(me, them.multiplier * 0.5)
            }
        }, 2 * duration);
    }
};
const swell = (them, multiplier, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.swollen) timer(() => {
        if (them.variables.swollen === undefined) them.variables.swollen = 0
        them.variables.swollen++;
        them.SIZE *= 1.005 * multiplier;
        setTimeout(() => {
            if(!them.variables.swollen) return;
            them.SIZE /= 1.005 * multiplier;
            them.variables.swollen--;
        }, 4 * duration * 1000);
    }, 1.5);
};
const shrivel = (them, multiplier, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.swollen) timer(() => {
        if (them.variables.swollen === undefined) them.variables.swollen = 0
        them.variables.swollen++;
        them.SIZE /= 1.005 * multiplier;
        setTimeout(() => {
            if (!them.variables.swollen) return;
            them.SIZE *= 1.005 * multiplier;
            them.variables.swollen--;
        }, 4 * duration * 1000);
    }, 1.5);
}

const funnySwell = (them, multiplier, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && them.SIZE <= 100) timer(() => {
        them.SIZE *= 1.003 * multiplier;
    }, 1.5 * duration);
};
const veryFunnySwell = (them, multiplier, duration) => {
    if (!them) return
    if (!them.invuln && !them.passive && !them.godmode) timer(() => {
        them.SIZE *= 1.003 * multiplier;
    }, 1.5 * duration);
};
const pepperspray = (them, amount, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.pepperspray && them.socket) {
        them.variables.pepperspray = true;
        them.socket.talk('pepperspray', true, amount);
        setTimeout(() => {
            them.variables.pepperspray = false;
            them.socket.talk('pepperspray', false, amount);
        }, duration * 1000);
    }
};
const lsd = (them, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.lsd && them.socket) {
        them.variables.lsd = true;
        them.socket.talk('lsd', true);
        setTimeout(() => {
            them.variables.lsd = false;
            them.socket.talk('lsd', false);
        }, duration * 1000);
    }
};
const torch = (me, them, multiplier, duration, team) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && them.team != team && !them.variables.poisoned) {
        let oddu = them.onDealtDamageUniv || (() => { });
        poison(me, them, multiplier, duration);
        them.onDealtDamageUniv = (me2, them2) => {
            if (me2 && them2) {
                if (oddu) oddu();
                torch(me2, them2, 1, 1, team);
            }
        }
        setTimeout(() => {
            them.onDealtDamageUniv = oddu;
        }, 2 * duration * 1000);
    }
};
const fireRandom = (gun, bulletArr, statArr, runThis) => {
    let rand = Math.floor(Math.random() * bulletArr.length);
    gun.bulletTypes = [bulletArr[rand]];
    gun.settings = statArr != undefined ? statArr[rand] : gun.settings;
    fireGun(gun);
};
const paralyze = (them, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode) timer(() => {
        them.velocity.x = 0;
        them.velocity.y = 0;
    }, duration);
};
const fireGun = (gun) => {
    gun.fire(
        gun.offset * Math.cos(gun.direction + gun.angle + gun.body.facing) + (1.35 * gun.length - gun.width * gun.settings.size / 2) * Math.cos(gun.angle + gun.body.facing),
        gun.offset * Math.sin(gun.direction + gun.angle + gun.body.facing) + (1.35 * gun.length - gun.width * gun.settings.size / 2) * Math.sin(gun.angle + gun.body.facing),
        gun.body.skill
    );
};
const animate = (me, tank, frames, duration, isFirstFrame, offset = 0, entities, resetToFirstFrame = false) => {
    let i = 1;
    if (entities) {
        entities.forEach(o => {
            if (o.settings.clearOnMasterUpgrade && o.master.id === me.id && o.id !== me.id && o !== me) o.kill();
        });
    }
    const animInterval = setInterval(() => {
        if (me.isAlive() && i <= frames) {
            me.upgrades = [];
            me.define(Class[`${tank}${(resetToFirstFrame && i == frames) ? 0 : isFirstFrame ? i + offset : frames - i}`]);
            i += 1;
        } else {
            if (me.isAlive && me.isShapeshifter) {
                me.onKill = exports.shapeshifter.ON_KILL
                me.upgrades = [];
            }
            clearInterval(animInterval);
        }
    }, duration);
};
const emp = (them, time) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode) {
        them.variables.emp = true;
        if (time != Infinity) setTimeout(() => {
            them.variables.emp = false;
        }, 1000 * time);
    }
};
const necro = (source, them, necroThis, initThis, options = {}) => {
    if (!them || !initThis) return false
    let theirType = options.type || 'food';
    let shootPermission = initThis.countsOwnKids ? initThis.countsOwnKids > initThis.children.length * initThis.body.skill.rld : initThis.body.maxChildren ? initThis.body.maxChildren > initThis.body.children.length * initThis.body.skill.rld : true;
    if (them.type == theirType && necroThis.includes(them.label) && shootPermission) {
        const theirFacing = them.facing;
        const theirSize = them.size;
        them.define(Class.genericEntity);
        initThis.bulletInit(them);
        them.team = source.team;
        them.master = source;
        them.color = source.color;
        them.facing = theirFacing;
        them.SIZE = theirSize;
        them.health.amount = them.health.max;
        them.onDamageDealt = (me2, them2) => {
            necro(me2.source, them2, necroThis, initThis);
        }
    }
    return true
};
const necroDrone = (me, them, necroThis, options = {}) => {
    return necro(me.source, them, necroThis, me.source.guns[me.gunIndex], options);
};
const necroRam = (me, them, necroThis, gunIndex, options = {}) => {
    return necro(me, them, necroThis, me.guns[gunIndex], options);
};
const spore = (me, them, gunIndex, amount) => {
    if (them.team === me.team || them?.source?.sanctuaryType !== "None" || (them.type !== "food" && them.type !== "tank" && them.type !== "crasher" && them.type !== "minion")) return;
    let gun = me.guns[gunIndex]
    let ogCanShoot = gun.canShoot

    gun.canShoot = true

    for (let i = 0; i < amount; i++) {
        if (gun.children.length > (gun.countsOwnKids || gun.body.maxChildren)) {
            gun.destroyOldest();
        }
        fireGun(gun)
        let child = gun.children[gun.children.length - 1]
        let max = 20
        let min = -20
        child.velocity.x = Math.floor(Math.random() * (max - min + 1)) + min;
        child.velocity.y = Math.floor(Math.random() * (max - min + 1)) + min;
        child.x = them.x
        child.y = them.y
    }

    gun.canShoot = ogCanShoot;
}

