function shootSettingsToGStat(settings) {
    const {
        reload,
        recoil,
        shudder,
        size,
        health,
        damage,
        pen,
        speed,
        maxSpeed,
        range,
        density,
        spray,
        resist
    } = settings;
    return [reload, recoil, shudder, size, health, damage, pen, speed, maxSpeed, range, density, spray, resist];
}
