const makeCeptionist = (type, name, options = {}) => {
    let output = deepCopy(type),
        bulletType = options.type || exports.basic2,
        bulletStats = options.bulletStats || [g.blank],
        bulletName = makeExportName(bulletType, 'CeptionistBullet', [bulletStats]),
        turretName = bulletName + 'Turret',
        tankStats = options.tankStats || [g.blank];

    if (!exports[turretName]) {
        exports[turretName] = deepCopy(bulletType);

        applyStats(exports[turretName].GUNS, [g.ceptionist_bullet, ...bulletStats], {
            propertyEdit: ((prop) => {
                prop.COLOR = 34;
            })
        });

        exports[bulletName] = {
            PARENT: [exports.bullet],
            GUNS: deepCopy(exports[turretName].GUNS || []),
            TURRETS: deepCopy(exports[turretName].TURRETS || []),
            PROPS: deepCopy(exports[turretName].PROPS || []),
            CONTROLLERS: ['alwaysFire']
        };

        if (exports[turretName].IS_ARENA_CLOSER) {
            exports[bulletName].DIES_TO_TEAM_BASE = false;
            exports[bulletName].GO_THRU_OBSTACLES = true;
            exports[bulletName].LAYER = 12;
        };
    }

    applyStats(output.GUNS, [g.ceptionist, ...tankStats], {
        shootEdit: ((prop) => {
            prop.TYPE = exports[bulletName]
        })
    });

    output.TURRETS = output.TURRETS || [];
    output.TURRETS.push({
        POSITION: [9, 0, 0, 0, 0, 1],
        TYPE: [exports[turretName], {
            COLOR: 34,
            INDEPENDENT: true
        }]
    });
    if (output.DANGER < 7) output.DANGER++;
    output.LABEL = (name || `${type.LABEL + 'ceptionist'}`) + (output.LABEL == base.LABEL && base.LABEL != 'Basic Basic' ? '\xB2' : '');
    return output;
};
