// Infiltration tanks
function infiltrationStats(stats = {}) {
    stats.fov = stats.fov ?? 1;
    stats.health = stats.health ?? 1;
    stats.shield = stats.shield ?? 1;
    stats.damage = stats.damage ?? 1;
    stats.speed = stats.speed ?? 1;

    return {
        FOV: base.FOV * 1.2 * stats.fov,
        HEALTH: base.HEALTH * 1.5 * stats.health,
        SHIELD: base.SHIELD * 1.5 * stats.shield,
        DAMAGE: base.DAMAGE * 1.5 * stats.damage,
        SPEED: base.SPEED * .8 * stats.speed,
        DENSITY: base.DENSITY * .8,
        PENETRATION: base.PENETRATION * 1.3,
        PUSHABILITY: base.PUSHABILITY * .4
    }
}

