for (const key in exports) {
    for (let i = 0; i < 5; i++) {
        if (exports[`UPGRADES_TIER_${i}`]) {
            let array = exports[`UPGRADES_TIER_${i}`];
            for (let i = 0; i < array.length; i++) {
                let tank = array[i];
                if (tank == null) {
                    throw new TypeError(`${key} was found to have an undefined upgrade on ${`TIER_${i}`} index ${i}`);
                }
            }
        }
    }
}